const express = require('express');
const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

const ROOT = '/app';
const DB_PATH = path.join(ROOT, 'data', 'patchpad.sqlite');
const SEED_PATH = '/assets/incident_seed.json';
const PORT = Number(process.env.PORT || 3000);

const app = express();
app.use(express.json({ limit: '2mb' }));
app.use(express.static(path.join(ROOT, 'public'), {
  extensions: ['html'],
  index: false,
}));

const db = new DatabaseSync(DB_PATH);

function nowIso() {
  return new Date().toISOString();
}

function loadSeed() {
  const raw = fs.readFileSync(SEED_PATH, 'utf8');
  return JSON.parse(raw);
}

function buildSeedContent(document) {
  const lines = [];
  for (const line of document.sections || []) {
    lines.push(line);
  }
  const count = Number(document.generatedLineCount || 0);
  const template = String(document.generatedLineTemplate || '');
  for (let i = 1; i <= count; i += 1) {
    lines.push(template.replaceAll('{n}', String(i)));
  }
  for (const line of document.tailSections || []) {
    lines.push(line);
  }
  return lines.join('\n');
}

function ensureSchema() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS documents (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      author TEXT NOT NULL,
      summary TEXT NOT NULL,
      content TEXT NOT NULL,
      current_revision INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS revisions (
      document_id TEXT NOT NULL,
      revision INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at TEXT NOT NULL,
      PRIMARY KEY (document_id, revision),
      FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE
    );
  `);
}

function seedDatabaseIfNeeded() {
  const count = db.prepare('SELECT COUNT(*) AS count FROM documents').get().count;
  if (count > 0) {
    return;
  }
  const seed = loadSeed().document;
  const content = buildSeedContent(seed);
  const timestamp = nowIso();
  const insertDocument = db.prepare(`
    INSERT INTO documents (id, title, author, summary, content, current_revision, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, 1, ?, ?)
  `);
  const insertRevision = db.prepare(`
    INSERT INTO revisions (document_id, revision, content, created_at)
    VALUES (?, 1, ?, ?)
  `);
  const tx = db.transaction(() => {
    insertDocument.run(seed.id, seed.title, seed.author, seed.summary, content, timestamp, timestamp);
    insertRevision.run(seed.id, content, timestamp);
  });
  tx();
}

function rowToDocument(row) {
  return {
    id: row.id,
    title: row.title,
    author: row.author,
    summary: row.summary,
    currentRevision: row.current_revision,
    content: row.content,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function getDocument(documentId) {
  const row = db.prepare('SELECT * FROM documents WHERE id = ?').get(documentId);
  return row ? rowToDocument(row) : null;
}

function listDocuments() {
  return db.prepare(`
    SELECT id, title, author, summary, current_revision AS currentRevision, updated_at AS updatedAt
    FROM documents
    ORDER BY created_at ASC, id ASC
  `).all();
}

function listRevisions(documentId) {
  return db.prepare(`
    SELECT revision, created_at AS createdAt,
           LENGTH(content) AS contentLength,
           substr(content, 1, 160) AS preview
    FROM revisions
    WHERE document_id = ?
    ORDER BY revision DESC
  `).all(documentId);
}

function getRevision(documentId, revision) {
  return db.prepare(`
    SELECT revision, created_at AS createdAt, content
    FROM revisions
    WHERE document_id = ? AND revision = ?
  `).get(documentId, revision);
}

function sendError(res, status, message, extra = {}) {
  res.status(status).json({ ok: false, error: message, ...extra });
}

function parseInteger(value) {
  if (typeof value === 'number' && Number.isInteger(value)) return value;
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    if (Number.isInteger(parsed)) return parsed;
  }
  return null;
}

ensureSchema();
seedDatabaseIfNeeded();

app.get('/api/bootstrap', (req, res) => {
  const documents = listDocuments();
  const activeDocument = documents[0] ? getDocument(documents[0].id) : null;
  if (!activeDocument) {
    return res.json({ ok: true, documents: [], activeDocument: null, revisions: [] });
  }
  return res.json({
    ok: true,
    documents,
    activeDocument: {
      id: activeDocument.id,
      title: activeDocument.title,
      author: activeDocument.author,
      summary: activeDocument.summary,
      currentRevision: activeDocument.currentRevision,
      content: activeDocument.content,
      createdAt: activeDocument.createdAt,
      updatedAt: activeDocument.updatedAt,
    },
    revisions: listRevisions(activeDocument.id),
  });
});

app.get('/api/documents', (req, res) => {
  res.json({ ok: true, documents: listDocuments() });
});

app.get('/api/documents/:id', (req, res) => {
  const doc = getDocument(req.params.id);
  if (!doc) {
    return sendError(res, 404, 'Document not found');
  }
  return res.json({ ok: true, document: doc, revisions: listRevisions(doc.id) });
});

app.get('/api/documents/:id/revisions', (req, res) => {
  const doc = getDocument(req.params.id);
  if (!doc) {
    return sendError(res, 404, 'Document not found');
  }
  return res.json({ ok: true, documentId: doc.id, revisions: listRevisions(doc.id) });
});

app.get('/api/documents/:id/revisions/:revision', (req, res) => {
  const doc = getDocument(req.params.id);
  if (!doc) {
    return sendError(res, 404, 'Document not found');
  }
  const revision = parseInteger(req.params.revision);
  if (revision === null) {
    return sendError(res, 400, 'Revision must be an integer');
  }
  const entry = getRevision(doc.id, revision);
  if (!entry) {
    return sendError(res, 404, 'Revision not found');
  }
  return res.json({
    ok: true,
    documentId: doc.id,
    revision: entry.revision,
    createdAt: entry.createdAt,
    content: entry.content,
  });
});

app.post('/api/documents/:id/save', (req, res) => {
  const doc = getDocument(req.params.id);
  if (!doc) {
    return sendError(res, 404, 'Document not found');
  }
  const body = req.body || {};
  if (body.documentId !== undefined && body.documentId !== doc.id) {
    return sendError(res, 400, 'Document id does not match the save target');
  }
  const baseRevision = parseInteger(body.baseRevision);
  if (baseRevision === null) {
    return sendError(res, 400, 'baseRevision must be an integer');
  }
  if (typeof body.content !== 'string') {
    return sendError(res, 400, 'content must be text');
  }
  if (baseRevision !== doc.currentRevision) {
    return sendError(res, 409, 'Save rejected because the document changed elsewhere', {
      currentRevision: doc.currentRevision,
    });
  }
  if (body.content === doc.content) {
    return res.json({
      ok: true,
      saved: false,
      currentRevision: doc.currentRevision,
      updatedAt: doc.updatedAt,
      revisionCount: listRevisions(doc.id).length,
    });
  }
  const nextRevision = doc.currentRevision + 1;
  const timestamp = nowIso();
  const tx = db.transaction(() => {
    db.prepare(`
      UPDATE documents
      SET content = ?, current_revision = ?, updated_at = ?
      WHERE id = ?
    `).run(body.content, nextRevision, timestamp, doc.id);
    db.prepare(`
      INSERT INTO revisions (document_id, revision, content, created_at)
      VALUES (?, ?, ?, ?)
    `).run(doc.id, nextRevision, body.content, timestamp);
  });
  tx();
  return res.json({
    ok: true,
    saved: true,
    currentRevision: nextRevision,
    updatedAt: timestamp,
    revisionCount: listRevisions(doc.id).length,
  });
});

app.get('/', (req, res) => {
  res.sendFile(path.join(ROOT, 'public', 'index.html'));
});

app.use((req, res) => {
  res.status(404).json({ ok: false, error: 'Not found' });
});

app.listen(PORT, '0.0.0.0', () => {
  console.log(`PatchPad listening on http://0.0.0.0:${PORT}`);
  console.log(`SQLite path: ${DB_PATH}`);
});

:root {
  color-scheme: dark;
  --bg: #0f172a;
  --panel: #111827;
  --panel-alt: #0b1220;
  --border: #25324a;
  --border-strong: #3a4b6a;
  --text: #e5eefb;
  --muted: #95a4bf;
  --accent: #7dd3fc;
  --accent-strong: #38bdf8;
  --success: #4ade80;
  --warning: #fbbf24;
  --danger: #fb7185;
  --selection: rgba(59, 130, 246, 0.35);
  --selection-strong: rgba(96, 165, 250, 0.5);
  --gutter: 72px;
  --editor-font: 14px;
  --editor-line: 22px;
  --shadow: 0 16px 40px rgba(2, 6, 23, 0.38);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at top, #172554 0, var(--bg) 58%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  overflow: hidden;
}

button,
input {
  font: inherit;
}

#app-shell {
  height: 100vh;
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: 12px;
  padding: 16px;
}

.topbar,
.toolbar,
.workspace,
.footer {
  min-width: 0;
}

.topbar,
.toolbar,
.editor-panel,
.side-panel > section,
.footer {
  border: 1px solid var(--border);
  border-radius: 16px;
  background: rgba(15, 23, 42, 0.82);
  backdrop-filter: blur(16px);
  box-shadow: var(--shadow);
}

.topbar {
  display: grid;
  grid-template-columns: minmax(320px, 1.2fr) minmax(340px, 1fr);
  gap: 16px;
  padding: 16px;
}

.brand {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.document-meta {
  margin-top: 8px;
  color: var(--muted);
  line-height: 1.4;
}

.report-list-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.document-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.doc-chip {
  border: 1px solid var(--border);
  background: rgba(17, 24, 39, 0.9);
  color: var(--text);
  border-radius: 999px;
  padding: 8px 12px;
  text-align: left;
  cursor: pointer;
}

.doc-chip.active {
  border-color: var(--accent-strong);
  box-shadow: inset 0 0 0 1px rgba(56, 189, 248, 0.35);
}

.doc-chip .doc-title {
  display: block;
  font-weight: 600;
}

.doc-chip .doc-meta {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  padding: 12px 16px 14px;
}

.toolbar button,
.preview-actions button {
  border: 1px solid var(--border);
  background: linear-gradient(180deg, #1f2937, #111827);
  color: var(--text);
  padding: 9px 14px;
  border-radius: 12px;
  cursor: pointer;
}

.toolbar button:hover,
.preview-actions button:hover,
.doc-chip:hover {
  border-color: var(--border-strong);
}

.toolbar button:focus-visible,
.preview-actions button:focus-visible,
.doc-chip:focus-visible,
#editorViewport:focus-visible,
input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.toolbar button.primary,
.preview-actions button.primary {
  border-color: rgba(56, 189, 248, 0.6);
  background: linear-gradient(180deg, rgba(14, 165, 233, 0.4), rgba(37, 99, 235, 0.35));
}

.toolbar-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: end;
}

.toolbar-group label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: var(--muted);
  font-size: 12px;
}

.toolbar-group input {
  width: min(32vw, 300px);
  min-width: 180px;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 9px 12px;
  background: rgba(17, 24, 39, 0.9);
  color: var(--text);
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(320px, 0.9fr);
  gap: 12px;
  min-height: 0;
}

.editor-panel,
.side-panel > section {
  min-height: 0;
}

.editor-panel {
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: 14px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 10px;
}

.status-line {
  color: var(--muted);
  font-size: 13px;
}

.editor-viewport {
  position: relative;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(6, 11, 25, 0.95), rgba(12, 18, 34, 0.96));
  min-height: 0;
  outline: none;
}

.editor-surface {
  position: relative;
  min-height: 100%;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: var(--editor-font);
  line-height: var(--editor-line);
  color: var(--text);
}

.editor-line {
  position: absolute;
  left: 0;
  right: 0;
  height: var(--editor-line);
  white-space: pre;
}

.line-number {
  position: sticky;
  left: 0;
  display: inline-block;
  width: var(--gutter);
  padding-right: 12px;
  text-align: right;
  color: var(--muted);
  user-select: none;
  background: linear-gradient(90deg, rgba(7, 10, 20, 0.95), rgba(7, 10, 20, 0.75));
}

.line-text {
  white-space: pre;
}

.selection {
  background: var(--selection);
  border-radius: 4px;
}

.selection.primary {
  background: var(--selection-strong);
}

.caret {
  position: absolute;
  width: 2px;
  background: var(--accent-strong);
  top: 2px;
  bottom: 2px;
  border-radius: 999px;
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.5);
  pointer-events: none;
}

.editor-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-top: 10px;
  color: var(--muted);
  font-size: 13px;
}

.side-panel {
  display: grid;
  grid-template-rows: minmax(0, 1fr) minmax(220px, 0.72fr);
  gap: 12px;
  min-height: 0;
}

.history-panel,
.preview-panel {
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: 14px;
  min-height: 0;
}

.revision-history {
  overflow: auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.revision-card {
  border: 1px solid var(--border);
  background: rgba(17, 24, 39, 0.84);
  border-radius: 14px;
  padding: 12px;
  display: grid;
  gap: 8px;
}

.revision-card.selected {
  border-color: var(--accent-strong);
}

.revision-card .revision-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.revision-card .revision-number {
  font-weight: 700;
}

.revision-card .revision-time {
  color: var(--muted);
  font-size: 12px;
}

.revision-card .revision-preview-snippet {
  color: #c6d4ec;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 12px;
  line-height: 1.45;
  max-height: 84px;
  overflow: auto;
  white-space: pre-wrap;
}

.revision-card .revision-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.revision-preview {
  margin: 0;
  overflow: auto;
  min-height: 0;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(6, 11, 25, 0.92);
  padding: 14px;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  color: #cfe2ff;
}

.preview-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  padding-top: 10px;
}

.footer {
  padding: 12px 16px;
}

.message-banner {
  color: var(--muted);
  min-height: 1.4em;
}

.message-banner.error {
  color: var(--danger);
}

.message-banner.success {
  color: var(--success);
}

.message-banner.warning {
  color: var(--warning);
}

.hidden {
  display: none !important;
}

@media (max-width: 1100px) {
  #app-shell {
    padding: 12px;
  }

  .topbar,
  .workspace {
    grid-template-columns: 1fr;
  }

  .side-panel {
    grid-template-rows: auto auto;
  }
}

const $ = (selector) => document.querySelector(selector);

const state = {
  documents: [],
  activeDocumentId: null,
  documentMeta: null,
  revisions: [],
  selectedRevision: null,
  previewRevision: null,
  text: '',
  savedText: '',
  baseRevision: 1,
  currentRevision: 1,
  saveMode: 'loading',
  message: 'Loading PatchPad…',
  messageType: '',
  selection: { start: 0, end: 0 },
  carets: [],
  undoStack: [],
  redoStack: [],
  drag: null,
  clipboardSelection: null,
  findQuery: '',
  replaceQuery: '',
  findMatchIndex: -1,
  matches: [],
  metrics: { charWidth: 8, lineHeight: 22, gutterWidth: 72 },
  renderScheduled: false,
  saveToken: 0,
  typingGroup: null,
};

const elements = {
  documentMeta: $('#documentMeta'),
  documentList: $('#documentList'),
  saveButton: $('#saveButton'),
  undoButton: $('#undoButton'),
  redoButton: $('#redoButton'),
  findInput: $('#findInput'),
  replaceInput: $('#replaceInput'),
  findPrevButton: $('#findPrevButton'),
  findNextButton: $('#findNextButton'),
  replaceCurrentButton: $('#replaceCurrentButton'),
  replaceAllButton: $('#replaceAllButton'),
  editorViewport: $('#editorViewport'),
  cursorInfo: $('#cursorInfo'),
  saveInfo: $('#saveInfo'),
  statusLine: $('#statusLine'),
  historySummary: $('#historySummary'),
  revisionHistory: $('#revisionHistory'),
  previewLabel: $('#previewLabel'),
  revisionPreview: $('#revisionPreview'),
  restoreRevisionButton: $('#restoreRevisionButton'),
  messageBanner: $('#messageBanner'),
};

const segmenter = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter('en', { granularity: 'grapheme' }) : null;
const wordSegmenter = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter('en', { granularity: 'word' }) : null;

function scheduleRender() {
  if (state.renderScheduled) return;
  state.renderScheduled = true;
  requestAnimationFrame(() => {
    state.renderScheduled = false;
    render();
  });
}

function setMessage(text, type = '') {
  state.message = text;
  state.messageType = type;
  scheduleRender();
}

function escapeHtml(text) {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function splitLines(text) {
  return text.split('\n');
}

function getLineStarts(text) {
  const starts = [0];
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '\n') starts.push(i + 1);
  }
  return starts;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function normalizeRange(start, end) {
  return start <= end ? { start, end } : { start: end, end: start };
}

function getGraphemeBoundaries(text) {
  if (!text) return [0];
  if (!segmenter) return Array.from({ length: text.length + 1 }, (_, i) => i);
  const boundaries = [0];
  for (const part of segmenter.segment(text)) {
    boundaries.push(part.index + part.segment.length);
  }
  return boundaries;
}

function prevGraphemeBoundary(text, offset) {
  if (offset <= 0) return 0;
  const boundaries = getGraphemeBoundaries(text);
  for (let i = boundaries.length - 1; i >= 0; i -= 1) {
    if (boundaries[i] < offset) return boundaries[i];
  }
  return 0;
}

function nextGraphemeBoundary(text, offset) {
  if (offset >= text.length) return text.length;
  const boundaries = getGraphemeBoundaries(text);
  for (const boundary of boundaries) {
    if (boundary > offset) return boundary;
  }
  return text.length;
}

function graphemeCount(text) {
  if (!text) return 0;
  if (!segmenter) return text.length;
  let count = 0;
  for (const _ of segmenter.segment(text)) count += 1;
  return count;
}

function lineIndexAndColumn(text, offset) {
  const safeOffset = clamp(offset, 0, text.length);
  const starts = getLineStarts(text);
  let lineIndex = 0;
  for (let i = 0; i < starts.length; i += 1) {
    if (starts[i] <= safeOffset) lineIndex = i;
    else break;
  }
  const lineStart = starts[lineIndex];
  const lineEnd = lineIndex + 1 < starts.length ? starts[lineIndex + 1] - 1 : text.length;
  const lineText = text.slice(lineStart, lineEnd);
  const prefix = text.slice(lineStart, safeOffset);
  return { lineIndex, column: graphemeCount(prefix), lineStart, lineEnd, lineText };
}

function offsetFromLineColumn(text, lineIndex, column) {
  const lines = splitLines(text);
  const starts = getLineStarts(text);
  const clampedLine = clamp(lineIndex, 0, lines.length - 1);
  const lineText = lines[clampedLine] || '';
  const boundaries = getGraphemeBoundaries(lineText);
  const graphemeLimit = boundaries.length - 1;
  const clampedColumn = clamp(column, 0, graphemeLimit);
  return starts[clampedLine] + boundaries[clampedColumn];
}

function findWordBoundary(text, offset, direction) {
  if (!text.length) return 0;
  if (!wordSegmenter) {
    const regex = /\w+/g;
    const matches = [...text.matchAll(regex)];
    if (direction > 0) {
      for (const match of matches) {
        const start = match.index;
        const end = start + match[0].length;
        if (end > offset) return start > offset ? start : end;
      }
      return text.length;
    }
    for (let i = matches.length - 1; i >= 0; i -= 1) {
      const start = matches[i].index;
      if (start < offset) return start;
    }
    return 0;
  }
  const segments = [...wordSegmenter.segment(text)];
  if (direction > 0) {
    for (const seg of segments) {
      const start = seg.index;
      const end = start + seg.segment.length;
      if (end > offset && seg.isWordLike) return start > offset ? start : end;
      if (start > offset && seg.isWordLike) return start;
    }
    return text.length;
  }
  for (let i = segments.length - 1; i >= 0; i -= 1) {
    const seg = segments[i];
    if (seg.index < offset && seg.isWordLike) return seg.index;
  }
  return 0;
}

function currentSelectionRange() {
  if (state.carets.length > 1) return null;
  const range = state.selection;
  if (!range) return null;
  return normalizeRange(range.start, range.end);
}

function hasSelection() {
  const range = currentSelectionRange();
  return !!range && range.start !== range.end;
}

function setSelection(start, end = start) {
  state.selection = normalizeRange(clamp(start, 0, state.text.length), clamp(end, 0, state.text.length));
  state.carets = [];
  state.drag = null;
  scheduleRender();
}

function setCaret(offset) {
  const safe = clamp(offset, 0, state.text.length);
  state.selection = { start: safe, end: safe };
  state.carets = [];
  state.drag = null;
  scheduleRender();
}

function setMultipleCarets(offsets) {
  state.carets = offsets.map((offset) => ({ start: clamp(offset, 0, state.text.length), end: clamp(offset, 0, state.text.length) }));
  if (state.carets.length === 0) state.carets = [{ start: 0, end: 0 }];
  state.selection = { start: state.carets[0].start, end: state.carets[0].end };
  scheduleRender();
}

function orderedRangesDescending(ranges) {
  return ranges
    .map((range) => normalizeRange(range.start, range.end))
    .sort((a, b) => b.start - a.start || b.end - a.end);
}

function replaceRangesWithText(text, ranges, insertedText) {
  let result = text;
  const sorted = orderedRangesDescending(ranges);
  for (const range of sorted) {
    result = result.slice(0, range.start) + insertedText + result.slice(range.end);
  }
  return result;
}

function applySelectionReplacement(insertedText) {
  const range = currentSelectionRange();
  if (!range) return false;
  state.text = state.text.slice(0, range.start) + insertedText + state.text.slice(range.end);
  const caret = range.start + insertedText.length;
  state.selection = { start: caret, end: caret };
  state.carets = [];
  return true;
}

function captureUndoSnapshot() {
  return {
    text: state.text,
    selection: { ...state.selection },
    carets: state.carets.map((range) => ({ ...range })),
    baseRevision: state.baseRevision,
    currentRevision: state.currentRevision,
    savedText: state.savedText,
  };
}

function pushUndoSnapshot(kind = 'edit') {
  const snapshot = captureUndoSnapshot();
  if (kind === 'typing' && state.typingGroup && Date.now() - state.typingGroup.startedAt < 900 && state.typingGroup.lastKind === 'typing') {
    state.typingGroup.snapshot = snapshot;
    state.typingGroup.lastTouched = Date.now();
    return;
  }
  if (state.typingGroup) {
    state.undoStack.push(state.typingGroup.snapshot);
    state.typingGroup = null;
  }
  state.undoStack.push(snapshot);
  state.redoStack = [];
  if (kind === 'typing') {
    state.typingGroup = {
      snapshot: captureUndoSnapshot(),
      startedAt: Date.now(),
      lastTouched: Date.now(),
      lastKind: 'typing',
    };
  }
}

function finalizeTypingGroup() {
  if (state.typingGroup) {
    state.undoStack.push(state.typingGroup.snapshot);
    state.typingGroup = null;
  }
}

function recordEdit(kind = 'edit') {
  if (kind === 'typing') {
    const snapshot = captureUndoSnapshot();
    if (state.typingGroup && Date.now() - state.typingGroup.startedAt < 900) {
      state.typingGroup.snapshot = snapshot;
      state.typingGroup.lastTouched = Date.now();
      state.typingGroup.lastKind = 'typing';
      return;
    }
    if (state.typingGroup) {
      state.undoStack.push(state.typingGroup.snapshot);
    }
    state.typingGroup = {
      snapshot,
      startedAt: Date.now(),
      lastTouched: Date.now(),
      lastKind: 'typing',
    };
  } else {
    finalizeTypingGroup();
    state.undoStack.push(captureUndoSnapshot());
    state.redoStack = [];
  }
}

function restoreSnapshot(snapshot) {
  state.text = snapshot.text;
  state.selection = { ...snapshot.selection };
  state.carets = snapshot.carets.map((range) => ({ ...range }));
  state.baseRevision = snapshot.baseRevision;
  state.currentRevision = snapshot.currentRevision;
  state.savedText = snapshot.savedText;
  state.drag = null;
  refreshFindMatches();
  updateDocumentDerivedState();
  scheduleRender();
}

function undo() {
  finalizeTypingGroup();
  const snapshot = state.undoStack.pop();
  if (!snapshot) return;
  state.redoStack.push(captureUndoSnapshot());
  restoreSnapshot(snapshot);
  setMessage('Undid the last edit.', 'success');
}

function redo() {
  finalizeTypingGroup();
  const snapshot = state.redoStack.pop();
  if (!snapshot) return;
  state.undoStack.push(captureUndoSnapshot());
  restoreSnapshot(snapshot);
  setMessage('Redid the last edit.', 'success');
}

function moveSelectionTo(offset, extend = false) {
  const safe = clamp(offset, 0, state.text.length);
  if (extend) {
    state.selection.end = safe;
    state.carets = [];
  } else {
    state.selection = { start: safe, end: safe };
    state.carets = [];
  }
  scheduleRender();
}

function textFromSelection() {
  const range = currentSelectionRange();
  if (!range || range.start === range.end) return '';
  return state.text.slice(range.start, range.end);
}

function deleteSelectionIfNeeded() {
  const range = currentSelectionRange();
  if (range && range.start !== range.end) {
    state.text = state.text.slice(0, range.start) + state.text.slice(range.end);
    state.selection = { start: range.start, end: range.start };
    return true;
  }
  return false;
}

function insertText(textToInsert, { typing = false } = {}) {
  if (!typing) recordEdit('edit');
  else recordEdit('typing');
  const selectionRange = currentSelectionRange();
  if (selectionRange && selectionRange.start !== selectionRange.end) {
    state.text = state.text.slice(0, selectionRange.start) + textToInsert + state.text.slice(selectionRange.end);
    const caret = selectionRange.start + textToInsert.length;
    state.selection = { start: caret, end: caret };
    state.carets = [];
  } else if (state.carets.length > 1) {
    const ranges = state.carets.map((range) => ({ start: range.start, end: range.end }));
    let nextText = state.text;
    const sorted = ranges.sort((a, b) => b.start - a.start || b.end - a.end);
    for (const range of sorted) {
      nextText = nextText.slice(0, range.start) + textToInsert + nextText.slice(range.end);
    }
    state.text = nextText;
    const nextPositions = ranges.map((range) => ({ start: range.start + textToInsert.length, end: range.start + textToInsert.length }));
    state.carets = nextPositions.sort((a, b) => a.start - b.start);
    state.selection = { ...state.carets[0] };
  } else {
    const caret = state.selection.end;
    state.text = state.text.slice(0, caret) + textToInsert + state.text.slice(caret);
    const nextCaret = caret + textToInsert.length;
    state.selection = { start: nextCaret, end: nextCaret };
  }
  markDirty();
  refreshFindMatches();
  updateDocumentDerivedState();
  scheduleRender();
}

function deleteByDirection(direction) {
  recordEdit('edit');
  const selectionRange = currentSelectionRange();
  if (selectionRange && selectionRange.start !== selectionRange.end) {
    state.text = state.text.slice(0, selectionRange.start) + state.text.slice(selectionRange.end);
    state.selection = { start: selectionRange.start, end: selectionRange.start };
    state.carets = [];
  } else if (state.carets.length > 1) {
    const ranges = [];
    for (const caret of state.carets) {
      const offset = caret.start;
      if (direction < 0 && offset === 0) continue;
      const start = direction < 0 ? prevGraphemeBoundary(state.text, offset) : offset;
      const end = direction < 0 ? offset : nextGraphemeBoundary(state.text, offset);
      if (start === end) continue;
      ranges.push({ start, end });
    }
    if (ranges.length === 0) return;
    state.text = replaceRangesWithText(state.text, ranges, '');
    const positions = ranges.map((range) => ({ start: range.start, end: range.start }));
    state.carets = positions.sort((a, b) => a.start - b.start);
    state.selection = { ...state.carets[0] };
  } else {
    const offset = state.selection.end;
    if (direction < 0 && offset === 0) return;
    const start = direction < 0 ? prevGraphemeBoundary(state.text, offset) : offset;
    const end = direction < 0 ? offset : nextGraphemeBoundary(state.text, offset);
    if (start === end) return;
    state.text = state.text.slice(0, start) + state.text.slice(end);
    state.selection = { start, end: start };
  }
  markDirty();
  refreshFindMatches();
  updateDocumentDerivedState();
  scheduleRender();
}

function indentSelection(outdent = false) {
  recordEdit('edit');
  const range = currentSelectionRange();
  const lines = splitLines(state.text);
  const lineStarts = getLineStarts(state.text);
  let startLine = 0;
  let endLine = lines.length - 1;
  if (range) {
    startLine = lineIndexAndColumn(state.text, range.start).lineIndex;
    const rangeEnd = Math.max(range.end, range.start);
    endLine = lineIndexAndColumn(state.text, Math.max(rangeEnd - 1, 0)).lineIndex;
  } else {
    const caretLine = lineIndexAndColumn(state.text, state.selection.end).lineIndex;
    startLine = endLine = caretLine;
  }
  const affected = [];
  for (let i = startLine; i <= endLine; i += 1) {
    affected.push(i);
  }
  let delta = 0;
  let nextText = state.text;
  for (const lineIndex of affected.slice().reverse()) {
    const start = lineStarts[lineIndex];
    if (outdent) {
      if (nextText.slice(start, start + 1) === '\t') {
        nextText = nextText.slice(0, start) + nextText.slice(start + 1);
        delta -= 1;
      } else if (nextText.slice(start, start + 2) === '  ') {
        nextText = nextText.slice(0, start) + nextText.slice(start + 2);
        delta -= 2;
      }
    } else {
      nextText = nextText.slice(0, start) + '\t' + nextText.slice(start);
      delta += 1;
    }
  }
  state.text = nextText;
  if (range) {
    state.selection = { start: range.start + delta, end: range.end + delta };
  } else {
    const caret = state.selection.end + delta;
    state.selection = { start: caret, end: caret };
  }
  markDirty();
  refreshFindMatches();
  updateDocumentDerivedState();
  scheduleRender();
}

function moveCaret(direction, { byWord = false, byLine = false, select = false, toStart = false, toEnd = false } = {}) {
  finalizeTypingGroup();
  const text = state.text;
  let anchor = state.selection.start;
  let focus = state.selection.end;
  if (state.selection.start !== state.selection.end && !select) {
    if (direction < 0 || toStart) focus = Math.min(state.selection.start, state.selection.end);
    else focus = Math.max(state.selection.start, state.selection.end);
  }
  let next = focus;
  if (toStart) {
    next = 0;
  } else if (toEnd) {
    next = text.length;
  } else if (byWord) {
    next = findWordBoundary(text, focus, direction);
  } else if (byLine) {
    const info = lineIndexAndColumn(text, focus);
    const lineText = splitLines(text)[info.lineIndex] || '';
    const targetLine = clamp(info.lineIndex + direction, 0, splitLines(text).length - 1);
    const targetLines = splitLines(text);
    const targetLineText = targetLines[targetLine] || '';
    const boundary = getGraphemeBoundaries(targetLineText);
    next = offsetFromLineColumn(text, targetLine, Math.min(info.column, boundary.length - 1));
  } else {
    next = clamp(focus + direction, 0, text.length);
    if (direction < 0) next = prevGraphemeBoundary(text, focus);
    else next = nextGraphemeBoundary(text, focus);
  }
  if (select) {
    state.selection = { start: anchor, end: next };
  } else {
    state.selection = { start: next, end: next };
  }
  state.carets = [];
  scheduleRender();
}

function selectAll() {
  state.selection = { start: 0, end: state.text.length };
  state.carets = [];
  scheduleRender();
}

function replaceCurrent() {
  const selectionText = textFromSelection();
  if (!selectionText) {
    findNext();
    return;
  }
  insertText(elements.replaceInput.value, { typing: false });
  setMessage('Replaced the current match.', 'success');
}

function replaceAll() {
  if (!state.findQuery) {
    setMessage('Enter a find query first.', 'warning');
    return;
  }
  const count = state.matches.length;
  if (!count) {
    setMessage('No matches to replace.', 'warning');
    return;
  }
  recordEdit('edit');
  const replacement = elements.replaceInput.value;
  const ranges = [...state.matches].sort((a, b) => b.start - a.start || b.end - a.end);
  let nextText = state.text;
  for (const match of ranges) {
    nextText = nextText.slice(0, match.start) + replacement + nextText.slice(match.end);
  }
  state.text = nextText;
  state.selection = { start: 0, end: 0 };
  state.carets = [];
  markDirty();
  refreshFindMatches();
  updateDocumentDerivedState();
  setMessage(`Replaced ${count} matches.`, 'success');
  scheduleRender();
}

function refreshFindMatches() {
  const query = state.findQuery;
  state.matches = [];
  state.findMatchIndex = -1;
  if (!query) return;
  let index = 0;
  while (index <= state.text.length) {
    const found = state.text.indexOf(query, index);
    if (found === -1) break;
    state.matches.push({ start: found, end: found + query.length });
    index = found + Math.max(1, query.length);
  }
  if (state.matches.length) {
    const selection = currentSelectionRange();
    if (selection) {
      const idx = state.matches.findIndex((range) => range.start === selection.start && range.end === selection.end);
      state.findMatchIndex = idx >= 0 ? idx : 0;
    } else {
      state.findMatchIndex = 0;
    }
  }
}

function selectMatch(index) {
  if (!state.matches.length) return;
  const normalized = ((index % state.matches.length) + state.matches.length) % state.matches.length;
  const match = state.matches[normalized];
  state.findMatchIndex = normalized;
  setSelection(match.start, match.end);
  ensureRangeVisible(match.start, match.end);
  updatePreviewForSelection();
}

function findNext() {
  if (!state.matches.length) {
    refreshFindMatches();
  }
  if (!state.matches.length) {
    setMessage('No matches found.', 'warning');
    return;
  }
  const current = state.findMatchIndex >= 0 ? state.findMatchIndex : -1;
  selectMatch(current + 1);
  setMessage(`Match ${state.findMatchIndex + 1} of ${state.matches.length}.`, 'success');
}

function findPrevious() {
  if (!state.matches.length) {
    refreshFindMatches();
  }
  if (!state.matches.length) {
    setMessage('No matches found.', 'warning');
    return;
  }
  const current = state.findMatchIndex >= 0 ? state.findMatchIndex : 0;
  selectMatch(current - 1);
  setMessage(`Match ${state.findMatchIndex + 1} of ${state.matches.length}.`, 'success');
}

function updateFindFromInput() {
  state.findQuery = elements.findInput.value;
  refreshFindMatches();
  if (state.findQuery && state.matches.length) {
    selectMatch(0);
    setMessage(`Found ${state.matches.length} matches.`, 'success');
  } else if (state.findQuery) {
    setMessage('No matches found.', 'warning');
  } else {
    setMessage('Find cleared.', '');
    state.findMatchIndex = -1;
  }
  scheduleRender();
}

function markDirty() {
  state.saveMode = state.text === state.savedText ? 'saved' : 'dirty';
  if (state.saveMode === 'dirty' && state.messageType !== 'error') {
    state.message = 'Unsaved changes';
  }
}

function updateDocumentDerivedState() {
  state.saveMode = state.text === state.savedText ? 'saved' : 'dirty';
  const info = lineIndexAndColumn(state.text, state.selection.end);
  elements.cursorInfo.textContent = `Line ${info.lineIndex + 1}, Column ${info.column + 1}`;
  const caretCount = state.carets.length > 1 ? `${state.carets.length} carets` : '1 caret';
  elements.saveInfo.textContent = `${state.saveMode === 'saved' ? 'Saved' : 'Unsaved'} · Revision ${state.currentRevision} · ${caretCount}`;
  elements.statusLine.textContent = state.saveMode === 'saved' ? `Revision ${state.currentRevision} is saved.` : `Editing revision ${state.baseRevision}.`;
  elements.historySummary.textContent = `${state.revisions.length} revision${state.revisions.length === 1 ? '' : 's'}`;
}

function ensureRangeVisible(start, end) {
  const viewport = elements.editorViewport;
  const lineStarts = getLineStarts(state.text);
  const startInfo = lineIndexAndColumn(state.text, start);
  const endInfo = lineIndexAndColumn(state.text, Math.max(end - 1, start));
  const top = startInfo.lineIndex * state.metrics.lineHeight;
  const bottom = (endInfo.lineIndex + 1) * state.metrics.lineHeight;
  if (top < viewport.scrollTop) viewport.scrollTop = Math.max(0, top - state.metrics.lineHeight * 2);
  if (bottom > viewport.scrollTop + viewport.clientHeight) {
    viewport.scrollTop = Math.max(0, bottom - viewport.clientHeight + state.metrics.lineHeight * 2);
  }
  const left = state.metrics.gutterWidth + startInfo.column * state.metrics.charWidth;
  const right = state.metrics.gutterWidth + endInfo.column * state.metrics.charWidth;
  if (left < viewport.scrollLeft + state.metrics.gutterWidth) {
    viewport.scrollLeft = Math.max(0, left - state.metrics.gutterWidth - 40);
  } else if (right > viewport.scrollLeft + viewport.clientWidth - 40) {
    viewport.scrollLeft = Math.max(0, right - viewport.clientWidth + 60);
  }
}

function getOffsetFromPoint(clientX, clientY) {
  const rect = elements.editorViewport.getBoundingClientRect();
  const x = clientX - rect.left + elements.editorViewport.scrollLeft - state.metrics.gutterWidth;
  const y = clientY - rect.top + elements.editorViewport.scrollTop;
  const lineIndex = clamp(Math.floor(y / state.metrics.lineHeight), 0, splitLines(state.text).length - 1);
  const lineText = splitLines(state.text)[lineIndex] || '';
  const graphemes = [...(segmenter ? segmenter.segment(lineText) : Array.from(lineText).map((segment, index) => ({ segment, index })) )];
  if (!graphemes.length) {
    return offsetFromLineColumn(state.text, lineIndex, 0);
  }
  const approxColumn = clamp(Math.round(x / state.metrics.charWidth), 0, graphemes.length);
  return offsetFromLineColumn(state.text, lineIndex, approxColumn);
}

function selectWordAtOffset(offset) {
  const before = state.text.slice(0, offset);
  const after = state.text.slice(offset);
  let start = offset;
  let end = offset;
  if (before) {
    const left = findWordBoundary(state.text, offset, -1);
    const right = findWordBoundary(state.text, offset, 1);
    start = left;
    end = right === offset ? nextGraphemeBoundary(state.text, offset) : right;
  } else {
    end = nextGraphemeBoundary(state.text, offset);
  }
  if (start === end) end = nextGraphemeBoundary(state.text, start);
  setSelection(start, end);
  ensureRangeVisible(start, end);
}

function selectLineAtOffset(offset) {
  const info = lineIndexAndColumn(state.text, offset);
  setSelection(info.lineStart, info.lineEnd);
  ensureRangeVisible(info.lineStart, info.lineEnd);
}

function handleMouseDown(event) {
  if (!state.text) return;
  elements.editorViewport.focus();
  const offset = getOffsetFromPoint(event.clientX, event.clientY);
  if (event.altKey || event.ctrlKey || event.metaKey) {
    const carets = state.carets.length > 0 ? state.carets.map((range) => range.start) : [state.selection.end];
    carets.push(offset);
    setMultipleCarets(carets);
    setMessage(`Added caret ${carets.length}.`, 'success');
    event.preventDefault();
    return;
  }
  if (event.detail >= 3) {
    selectLineAtOffset(offset);
  } else if (event.detail === 2) {
    selectWordAtOffset(offset);
  } else if (event.shiftKey) {
    state.selection.end = offset;
    state.carets = [];
    scheduleRender();
  } else {
    setCaret(offset);
  }
  state.drag = { anchor: offset, active: true, line: lineIndexAndColumn(state.text, offset).lineIndex };
  event.preventDefault();
}

function handleMouseMove(event) {
  if (!state.drag || !state.drag.active) return;
  const offset = getOffsetFromPoint(event.clientX, event.clientY);
  state.selection = { start: state.drag.anchor, end: offset };
  state.carets = [];
  ensureRangeVisible(state.selection.start, state.selection.end);
  scheduleRender();
}

function handleMouseUp() {
  if (state.drag) state.drag.active = false;
}

function handleCopy(event) {
  const selectionText = textFromSelection();
  if (!selectionText) return;
  event.clipboardData.setData('text/plain', selectionText);
  event.preventDefault();
}

function handleCut(event) {
  const selectionText = textFromSelection();
  if (!selectionText) return;
  event.clipboardData.setData('text/plain', selectionText);
  deleteSelectionIfNeeded();
  markDirty();
  refreshFindMatches();
  updateDocumentDerivedState();
  scheduleRender();
  event.preventDefault();
}

function handlePaste(event) {
  const text = event.clipboardData.getData('text/plain');
  if (typeof text !== 'string') return;
  insertText(text, { typing: false });
  event.preventDefault();
}

function handleKeyDown(event) {
  if (event.metaKey || event.ctrlKey) {
    const key = event.key.toLowerCase();
    if (key === 's') {
      event.preventDefault();
      saveDocument();
      return;
    }
    if (key === 'z') {
      event.preventDefault();
      if (event.shiftKey) redo();
      else undo();
      return;
    }
    if (key === 'y') {
      event.preventDefault();
      redo();
      return;
    }
    if (key === 'f') {
      event.preventDefault();
      elements.findInput.focus();
      elements.findInput.select();
      return;
    }
    if (key === 'a') {
      event.preventDefault();
      selectAll();
      return;
    }
  }

  if (event.key === 'Escape') {
    event.preventDefault();
    elements.findInput.focus();
    return;
  }

  if (event.key === 'Tab') {
    event.preventDefault();
    indentSelection(event.shiftKey);
    return;
  }

  if (event.key === 'Backspace') {
    event.preventDefault();
    deleteByDirection(-1);
    return;
  }

  if (event.key === 'Delete') {
    event.preventDefault();
    deleteByDirection(1);
    return;
  }

  if (event.key === 'Enter') {
    event.preventDefault();
    insertText('\n', { typing: true });
    return;
  }

  if (event.key === 'ArrowLeft') {
    event.preventDefault();
    if (event.metaKey || event.ctrlKey) moveCaret(-1, { byWord: true, select: event.shiftKey });
    else moveCaret(-1, { select: event.shiftKey });
    return;
  }

  if (event.key === 'ArrowRight') {
    event.preventDefault();
    if (event.metaKey || event.ctrlKey) moveCaret(1, { byWord: true, select: event.shiftKey });
    else moveCaret(1, { select: event.shiftKey });
    return;
  }

  if (event.key === 'ArrowUp') {
    event.preventDefault();
    moveCaret(-1, { byLine: true, select: event.shiftKey });
    return;
  }

  if (event.key === 'ArrowDown') {
    event.preventDefault();
    moveCaret(1, { byLine: true, select: event.shiftKey });
    return;
  }

  if (event.key === 'Home') {
    event.preventDefault();
    moveCaret(-1, { toStart: !event.ctrlKey && !event.metaKey, select: event.shiftKey });
    return;
  }

  if (event.key === 'End') {
    event.preventDefault();
    moveCaret(1, { toEnd: !event.ctrlKey && !event.metaKey, select: event.shiftKey });
    return;
  }

  if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey) {
    event.preventDefault();
    insertText(event.key, { typing: true });
  }
}

function applyPreviewRevision(revision) {
  if (!revision) return;
  state.previewRevision = revision;
