  const bootstrap = await fetch('http://127.0.0.1:3000/api/bootstrap').then(r => r.json());
  const doc = bootstrap.activeDocument;
  const res = await fetch(`http://127.0.0.1:3000/api/documents/${doc.id}/save`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ documentId: doc.id, baseRevision: doc.currentRevision, content: doc.content }),
  });
  const data = await res.json();
  console.log(JSON.stringify({ status: res.status, ...data }));
})();
